package dev.starfold;

import org.joml.Quaterniond;
import org.joml.Quaterniondc;
import org.joml.Vector3d;

/** Upright ground navigation (+Z look, +X screen-left). Orbital six-axis controls stay unchanged. */
public final class GroundView {
    public static final double PITCH_LIMIT=89.5;
    /** Remove existing roll while keeping the forward ray, except for the half-degree pole margin. */
    public static Quaterniond upright(Quaterniondc attitude){
        if(attitude==null||!Double.isFinite(attitude.lengthSquared())||attitude.lengthSquared()<1e-12)throw new IllegalArgumentException("Ground attitude");
        var q=new Quaterniond(attitude).normalize();var left=q.transform(new Vector3d(1,0,0));
        double fallback=Math.toDegrees(Math.atan2(left.z,left.x));
        return OrbitAttitude.upright(OrbitAttitude.yaw(q,fallback),Math.clamp(OrbitAttitude.pitch(q),-PITCH_LIMIT,PITCH_LIMIT));
    }
    /** Degrees: yaw about chart +Y, pitch bounded about the upright horizontal left axis. */
    public static Quaterniond turn(Quaterniondc attitude,double yaw,double pitch){
        if(!Double.isFinite(yaw)||!Double.isFinite(pitch))throw new IllegalArgumentException("Mouse input");
        var q=upright(attitude);
        return OrbitAttitude.upright(OrbitAttitude.yaw(q,0)+yaw,Math.clamp(OrbitAttitude.pitch(q)+pitch,-PITCH_LIMIT,PITCH_LIMIT));
    }
    /** Minecraft camera uses -Z look and -X left; this conversion does not add roll. */
    public static Quaterniond camera(Quaterniondc attitude){return new Quaterniond(attitude).rotateY(Math.PI);}
    private GroundView(){}
}

package dev.starfold;

import dev.starfold.BentStripGeometry.Point;
import org.joml.Quaterniond;

/** Unit AABB walking and flight. Root changes transport pose AND orientation, never deform blocks. */
public final class GroundMotion {
    public record State(GroundSpace.Pose pose,double vertical,boolean grounded,boolean flying,boolean jumpHeld,boolean cut,double qx,double qy,double qz,double qw){
        public State{double n=qx*qx+qy*qy+qz*qz+qw*qw;if(pose==null||!Double.isFinite(vertical)||Math.abs(vertical)>3||!Double.isFinite(n)||Math.abs(n-1)>.001)throw new IllegalArgumentException("Body");}
        public State(GroundSpace.Pose p,double v,boolean grounded,boolean flying,boolean jump,boolean cut,Quaterniond q){this(p,v,grounded,flying,jump,cut,q.x,q.y,q.z,q.w);}
        public Quaterniond orientation(){return new Quaterniond(qx,qy,qz,qw);}
    }
    public static State spawn(GroundWorld w,GroundSpace.Pose pose,double yaw){if(!clear(w,pose))throw new IllegalStateException("Spawn occupied; no blocks removed");return new State(pose,0,false,false,false,false,new Quaterniond().rotationY(yaw));}
    public static State step(GroundWorld w,State old,PlanetMotion.Input in,boolean toggle){
        boolean flying=toggle?!old.flying:old.flying,jump=in.rise()>0;double vy=toggle?0:old.vertical;var p=old.pose.point();var chart=new GroundChart(old.pose.face());var q=GroundView.upright(in.orientation());
        var up=new Point(0,1,0);var f=PlanetMotion.direction(q,0,0,1);var l=PlanetMotion.direction(q,1,0,0);var horizontal=new Point(f.x(),0,f.z());if(horizontal.length()<1e-5)horizontal=l.cross(up);horizontal=PlanetSpace.unit(horizontal);var d=horizontal.scale(in.forward()).add(up.cross(horizontal).scale(in.left()));if(d.length()>1)d=PlanetSpace.unit(d);
        if(flying){vy=0;d=(in.direct()?f.scale(in.forward()).add(l.scale(in.left())):d).add(up.scale(in.rise()));d=d.scale((in.fast()?1.2:.35)/Math.max(1,d.length()));}
        else{if(old.grounded&&jump&&!old.jumpHeld)vy=.42;else vy=Math.max(-3,vy-.08);d=d.scale(in.fast()?.30:.215).add(up.scale(vy));}
        d=new Point(d.x(),Math.clamp(p.y()+d.y(),GroundSpace.MIN+1,GroundSpace.CEILING)-p.y(),d.z());
        var end=ChartLabMotion.sweep(p,d,(x,y,z)->w.material(chart,x,y,z)!=0);
        // No fabricated invisible wall. Explicitly refuse a step into an unavailable net quadrant.
        if(!chart.bodyFits(end))return new State(old.pose,0,old.grounded,flying,jump,true,q);
        boolean grounded=false;if(!flying){var probe=ChartLabMotion.sweep(end,new Point(0,-.06,0),(x,y,z)->w.material(chart,x,y,z)!=0);grounded=end.y()-probe.y()<.045;if(grounded&&vy<0||vy>0&&end.y()-p.y()<vy*.25)vy=0;}
        var r=GroundSpace.canonical(old.pose.face(),end);q.premul(new Quaterniond().rotationY(-r.turns()*Math.PI/2)).normalize();
        return new State(r.pose(),vy,grounded,flying,jump,false,q);
    }
    public static boolean clear(GroundWorld w,GroundSpace.Pose pose){var chart=new GroundChart(pose.face());var p=pose.point();if(!chart.bodyFits(p))return false;for(int x=(int)Math.floor(p.x()-.3);x<=Math.floor(p.x()+.3);x++)for(int y=(int)Math.floor(p.y()-.9);y<=Math.floor(p.y()+.9);y++)for(int z=(int)Math.floor(p.z()-.3);z<=Math.floor(p.z()+.3);z++)if(w.material(chart,x,y,z)!=0)return false;return true;}
    public static boolean intersects(GroundSpace.Pose pose,CubeSurfaceTopology.Cell cell){var t=new GroundChart(pose.face()).tile(cell.face());if(t==null)return false;var d=t.point(new Point(cell.u()+.5,cell.h()+.5,cell.v()+.5)).sub(pose.point());return Math.abs(d.x())<.802&&Math.abs(d.y())<1.402&&Math.abs(d.z())<.802;}
    private GroundMotion(){}
}

